{
  "name": "Unibelands 3",
  "description": "An optimized panoramic visualizer featuring a parallax cloud system using Three.js, a scrolling horizon, and interactive navigation."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export const CLOUD_URLS = [
  'https://i.imgur.com/JTrVDQ3.png', 
  'https://i.imgur.com/58lHfHw.png',
  'https://i.imgur.com/X8FIpPe.png', 
  'https://i.imgur.com/hcdTnXq.png',
  'https://i.imgur.com/C08w8E1.png', 
  'https://i.imgur.com/Nypf6gX.png',
  'https://i.imgur.com/jd76dmd.png'
];

export const ASSETS = {
  ROOM_LEFT: 'https://i.imgur.com/P2lPVcP.jpeg',
  ROOM_CENTER: 'https://i.imgur.com/P2lPVcP.jpeg',
  ROOM_RIGHT: 'https://i.imgur.com/P2lPVcP.jpeg',
  HORIZON: 'https://i.imgur.com/qJjdsKJ.png'
};

export const SCROLL_SNAP_ALIGNMENT = {
  LEFT: 0,
  CENTER: 1,
  RIGHT: 2
};

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { CLOUD_URLS } from '../constants';

interface CloudSprite extends THREE.Mesh {
  userData: {
    speed: number;
    parallax: number;
    baseX?: number;
  };
}

interface CloudBackgroundProps {
  scrollRef: React.MutableRefObject<number>;
}

const CloudBackground: React.FC<CloudBackgroundProps> = ({ scrollRef }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.OrthographicCamera | null>(null);
  const cloudsRef = useRef<CloudSprite[]>([]);
  const frameIdRef = useRef<number>(0);

  useEffect(() => {
    if (!containerRef.current) return;

    const container = containerRef.current;
    const w = container.clientWidth;
    const h = container.clientHeight;
    const aspect = w / h;

    // 1. Scene
    const scene = new THREE.Scene();
    sceneRef.current = scene;

    // 2. Camera
    const frustumSize = 1000;
    const camera = new THREE.OrthographicCamera(
      frustumSize * aspect / -2,
      frustumSize * aspect / 2,
      frustumSize / 2,
      frustumSize / -2,
      1,
      2000
    );
    camera.position.z = 1000;
    cameraRef.current = camera;

    // 3. Renderer
    const renderer = new THREE.WebGLRenderer({ 
      alpha: true, 
      antialias: false,
      powerPreference: "high-performance" 
    });
    renderer.setSize(w, h);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // 4. Create Clouds
    const loader = new THREE.TextureLoader();
    const cloudGeo = new THREE.PlaneGeometry(300, 200);

    const setupCloud = (sprite: CloudSprite, isBack: boolean, isMid: boolean, width: number, height: number) => {
      const rangeX = width * 1.5;
      const rangeY = height * 0.8;

      sprite.position.x = (Math.random() * rangeX * 2) - rangeX;
      sprite.position.y = (Math.random() * rangeY) - (rangeY / 2);

      if (isBack) {
        sprite.position.z = -100;
        sprite.scale.set(1.5, 1.5, 1);
        // @ts-ignore - Material opacity exists on MeshBasicMaterial
        sprite.material.opacity = 0.4;
        sprite.userData = { speed: 0.2, parallax: 0.1 };
      } else if (isMid) {
        sprite.position.z = 0;
        sprite.scale.set(1.2, 1.2, 1);
        // @ts-ignore
        sprite.material.opacity = 0.8;
        sprite.userData = { speed: 0.5, parallax: 0.3 };
      } else {
        sprite.position.z = 100;
        sprite.scale.set(1.8, 1.8, 1);
        // @ts-ignore
        sprite.material.opacity = 1.0;
        sprite.userData = { speed: 0.8, parallax: 0.6 };
      }
    };

    // Create 15 clouds
    for (let i = 0; i < 15; i++) {
      const url = CLOUD_URLS[i % CLOUD_URLS.length];
      loader.load(url, (texture) => {
        const material = new THREE.MeshBasicMaterial({
          map: texture,
          transparent: true,
          depthWrite: false,
        });

        const sprite = new THREE.Mesh(cloudGeo, material) as CloudSprite;
        const isBack = i % 3 === 0;
        const isMid = i % 3 === 1;

        setupCloud(sprite, isBack, isMid, w, h);
        scene.add(sprite);
        cloudsRef.current.push(sprite);
      });
    }

    // Animation Loop
    const animate = () => {
      frameIdRef.current = requestAnimationFrame(animate);

      // Current scroll position from the parent via ref
      const currentScrollX = scrollRef.current;
      const viewerWidth = window.innerWidth;
      // Parallax relative to center
      const relativeScroll = currentScrollX - viewerWidth; 

      cloudsRef.current.forEach(cloud => {
        // Wind movement
        cloud.position.x -= cloud.userData.speed;

        // Reset loop
        if (cloud.position.x < -viewerWidth * 1.5) {
            cloud.position.x = viewerWidth * 1.5;
            // Also reset base if we are tracking it, though simplistic loop reset is often enough for this effect
            if (cloud.userData.baseX !== undefined) {
               cloud.userData.baseX = viewerWidth * 1.5;
            }
        }

        // Parallax Logic
        if (cloud.userData.baseX === undefined) {
            cloud.userData.baseX = cloud.position.x;
        }

        // Update base with wind
        cloud.userData.baseX -= cloud.userData.speed;
        if (cloud.userData.baseX < -viewerWidth * 1.5) {
            cloud.userData.baseX = viewerWidth * 1.5;
        }

        // Apply visual position = Base Position - (Scroll Offset * Depth Factor)
        cloud.position.x = cloud.userData.baseX - (relativeScroll * cloud.userData.parallax);
      });

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();

    // Handle Resize
    const handleResize = () => {
      if (!containerRef.current || !rendererRef.current || !cameraRef.current) return;
      const newW = containerRef.current.clientWidth;
      const newH = containerRef.current.clientHeight;
      const newAspect = newW / newH;

      const newFrustum = 1000;
      cameraRef.current.left = -newFrustum * newAspect / 2;
      cameraRef.current.right = newFrustum * newAspect / 2;
      cameraRef.current.top = newFrustum / 2;
      cameraRef.current.bottom = -newFrustum / 2;
      cameraRef.current.updateProjectionMatrix();

      rendererRef.current.setSize(newW, newH);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(frameIdRef.current);
      if (rendererRef.current && containerRef.current) {
        containerRef.current.removeChild(rendererRef.current.domElement);
        rendererRef.current.dispose();
      }
      // Simple texture disposal
      cloudsRef.current.forEach(c => {
        (c.material as THREE.Material).dispose();
        c.geometry.dispose();
      });
      cloudsRef.current = [];
    };
  }, [scrollRef]);

  return (
    <div 
      ref={containerRef} 
      className="absolute inset-0 w-full h-full pointer-events-none"
      style={{ background: 'linear-gradient(180deg, #1E90FF 0%, #87CEFA 100%)', zIndex: 0 }}
    />
  );
};

export default CloudBackground;

import React, { useRef, useState, useEffect, useCallback } from 'react';
import CloudBackground from './CloudBackground';
import { ASSETS } from '../constants';

const PanoramaViewer: React.FC = () => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Ref shared with Three.js to avoid re-rendering React component on every scroll frame
  const scrollXRef = useRef<number>(0);

  // Local state for UI updates only (debounced or throttled naturally by React batching)
  const [activeDot, setActiveDot] = useState(1);
  const [horizonOffset, setHorizonOffset] = useState(0);

  // Initial scroll to center
  useEffect(() => {
    if (scrollContainerRef.current) {
      const startX = window.innerWidth;
      scrollContainerRef.current.scrollTo({ left: startX, behavior: 'auto' });
      scrollXRef.current = startX;
      setHorizonOffset(startX);
    }
  }, []);

  const handleScroll = useCallback(() => {
    if (!scrollContainerRef.current) return;

    const currentX = scrollContainerRef.current.scrollLeft;
    const width = window.innerWidth;

    // Update ref for Three.js
    scrollXRef.current = currentX;

    // Update Horizon Parallax (using state here for simplicity, 
    // though direct DOM manipulation is more performant for high-freq updates, 
    // React 18 usually handles this well enough for this complexity)
    setHorizonOffset(currentX);

    // Update Dots
    const newActiveIndex = Math.round(currentX / width);
    if (newActiveIndex !== activeDot) {
      setActiveDot(newActiveIndex);
    }
  }, [activeDot]);

  const scrollToPanel = (index: number) => {
    if (scrollContainerRef.current) {
      const target = index * window.innerWidth;
      scrollContainerRef.current.scrollTo({ left: target, behavior: 'smooth' });
    }
  };

  const preventVerticalScroll = (e: React.WheelEvent) => {
    if (e.deltaY !== 0 && scrollContainerRef.current) {
      // Horizontal scroll with vertical wheel
      scrollContainerRef.current.scrollLeft += e.deltaY;
    }
  };

  return (
    <div className="relative w-full h-screen overflow-hidden bg-black select-none flex flex-col">
      {/* 1. Sky & Clouds (Z-0) */}
      <CloudBackground scrollRef={scrollXRef} />

      {/* 2. Floor / Rooms (Z-5) */}
      <div 
        ref={scrollContainerRef}
        onScroll={handleScroll}
        onWheel={preventVerticalScroll}
        className="no-scrollbar relative flex flex-row w-full h-[55vh] min-h-[400px] overflow-x-auto scroll-smooth snap-x snap-mandatory z-[5] mt-auto"
        style={{ scrollBehavior: 'smooth' }}
      >
        {/* Pane 0: West */}
        <div className="min-w-[100vw] w-screen h-full flex-shrink-0 bg-black relative snap-start overflow-hidden">
          <img 
            src={ASSETS.ROOM_LEFT} 
            alt="Vista Oeste" 
            className="w-full h-full object-cover object-left pointer-events-none select-none"
          />
          <div className="absolute bottom-20 left-10 text-white/50 text-sm font-mono">VISTA OESTE</div>
        </div>

        {/* Pane 1: North (Center) */}
        <div className="min-w-[100vw] w-screen h-full flex-shrink-0 bg-black relative snap-start overflow-hidden">
          <img 
            src={ASSETS.ROOM_CENTER} 
            alt="Vista Norte" 
            className="w-full h-full object-cover object-center pointer-events-none select-none"
          />
          <div className="absolute bottom-20 left-1/2 -translate-x-1/2 text-white/50 text-sm font-mono">VISTA NORTE</div>
        </div>

        {/* Pane 2: East */}
        <div className="min-w-[100vw] w-screen h-full flex-shrink-0 bg-black relative snap-start overflow-hidden">
          <img 
            src={ASSETS.ROOM_RIGHT} 
            alt="Vista Este" 
            className="w-full h-full object-cover object-right pointer-events-none select-none"
          />
          <div className="absolute bottom-20 right-10 text-white/50 text-sm font-mono">VISTA ESTE</div>
        </div>
      </div>

      {/* 3. Horizon Layer (Z-10) */}
      <div 
        className="absolute w-full h-[30vh] min-h-[200px] pointer-events-none overflow-hidden z-10"
        style={{ bottom: 'calc(55vh - 50px)' }} // Overlap logic from original CSS
      >
        <div 
          className="flex w-[300vw] h-full will-change-transform"
          style={{ transform: `translateX(-${horizonOffset}px)` }}
        >
            <img 
              src={ASSETS.HORIZON} 
              alt="Horizonte" 
              className="w-full h-full object-contain object-bottom opacity-90"
            />
        </div>
      </div>

      {/* 4. UI Indicators (Z-50) */}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 flex gap-4 z-50 bg-black/40 backdrop-blur-md px-4 py-2 rounded-full border border-white/10 shadow-2xl transition-transform hover:scale-105">
        {[0, 1, 2].map((idx) => (
          <button
            key={idx}
            onClick={() => scrollToPanel(idx)}
            aria-label={`Go to panel ${idx}`}
            className={`w-2 h-2 rounded-full transition-all duration-300 ${
              activeDot === idx 
                ? 'bg-white scale-125' 
                : 'bg-white/30 hover:bg-white scale-100'
            }`}
          />
        ))}
      </div>
    </div>
  );
};

export default PanoramaViewer;

