import React, { useRef, useState, useEffect, useCallback } from 'react';
import CloudBackground from './CloudBackground';
import { ASSETS } from '../constants';

const PanoramaViewer: React.FC = () => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Ref shared with Three.js to avoid re-rendering React component on every scroll frame
  const scrollXRef = useRef<number>(0);

  // Local state for UI updates only (debounced or throttled naturally by React batching)
  const [activeDot, setActiveDot] = useState(1);
  const [horizonOffset, setHorizonOffset] = useState(0);

  // Initial scroll to center
  useEffect(() => {
    if (scrollContainerRef.current) {
      const startX = window.innerWidth;
      scrollContainerRef.current.scrollTo({ left: startX, behavior: 'auto' });
      scrollXRef.current = startX;
      setHorizonOffset(startX);
    }
  }, []);

  const handleScroll = useCallback(() => {
    if (!scrollContainerRef.current) return;

    const currentX = scrollContainerRef.current.scrollLeft;
    const width = window.innerWidth;

    // Update ref for Three.js
    scrollXRef.current = currentX;

    // Update Horizon Parallax (using state here for simplicity, 
    // though direct DOM manipulation is more performant for high-freq updates, 
    // React 18 usually handles this well enough for this complexity)
    setHorizonOffset(currentX);

    // Update Dots
    const newActiveIndex = Math.round(currentX / width);
    if (newActiveIndex !== activeDot) {
      setActiveDot(newActiveIndex);
    }
  }, [activeDot]);

  const scrollToPanel = (index: number) => {
    if (scrollContainerRef.current) {
      const target = index * window.innerWidth;
      scrollContainerRef.current.scrollTo({ left: target, behavior: 'smooth' });
    }
  };

  const preventVerticalScroll = (e: React.WheelEvent) => {
    if (e.deltaY !== 0 && scrollContainerRef.current) {
      // Horizontal scroll with vertical wheel
      scrollContainerRef.current.scrollLeft += e.deltaY;
    }
  };

  return (
    <div className="relative w-full h-screen overflow-hidden bg-black select-none flex flex-col">
      {/* 1. Sky & Clouds (Z-0) */}
      <CloudBackground scrollRef={scrollXRef} />

      {/* 2. Floor / Rooms (Z-20: Foreground, on top of horizon) */}
      <div 
        ref={scrollContainerRef}
        onScroll={handleScroll}
        onWheel={preventVerticalScroll}
        className="no-scrollbar relative flex flex-row w-full h-[55vh] min-h-[400px] overflow-x-auto scroll-smooth snap-x snap-mandatory z-[20] mt-auto"
        style={{ scrollBehavior: 'smooth' }}
      >
        {/* Pane 0: West */}
        <div className="min-w-[100vw] w-screen h-full flex-shrink-0 bg-black relative snap-start overflow-hidden">
          <img 
            src={ASSETS.ROOM_LEFT} 
            alt="Vista Oeste" 
            className="w-full h-full object-cover object-left pointer-events-none select-none"
          />
          <div className="absolute bottom-20 left-10 text-white/50 text-sm font-mono">VISTA OESTE</div>
        </div>

        {/* Pane 1: North (Center) */}
        <div className="min-w-[100vw] w-screen h-full flex-shrink-0 bg-black relative snap-start overflow-hidden">
          <img 
            src={ASSETS.ROOM_CENTER} 
            alt="Vista Norte" 
            className="w-full h-full object-cover object-center pointer-events-none select-none"
          />
          <div className="absolute bottom-20 left-1/2 -translate-x-1/2 text-white/50 text-sm font-mono">VISTA NORTE</div>
        </div>

        {/* Pane 2: East */}
        <div className="min-w-[100vw] w-screen h-full flex-shrink-0 bg-black relative snap-start overflow-hidden">
          <img 
            src={ASSETS.ROOM_RIGHT} 
            alt="Vista Este" 
            className="w-full h-full object-cover object-right pointer-events-none select-none"
          />
          <div className="absolute bottom-20 right-10 text-white/50 text-sm font-mono">VISTA ESTE</div>
        </div>
      </div>

      {/* 3. Horizon Layer (Z-10: Middle ground, behind floor) */}
      <div 
        className="absolute w-full h-[20vh] min-h-[150px] pointer-events-none overflow-hidden z-10"
        style={{ bottom: 'calc(55vh - 30px)' }} // Slight overlap behind floor to ensure continuity
      >
        <div 
          className="flex w-[300vw] h-full will-change-transform"
          style={{ transform: `translateX(-${horizonOffset}px)` }}
        >
            <img 
              src={ASSETS.HORIZON} 
              alt="Horizonte" 
              className="w-full h-full object-cover object-bottom opacity-90"
            />
        </div>
      </div>

      {/* 4. UI Indicators (Z-50) */}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 flex gap-4 z-50 bg-black/40 backdrop-blur-md px-4 py-2 rounded-full border border-white/10 shadow-2xl transition-transform hover:scale-105">
        {[0, 1, 2].map((idx) => (
          <button
            key={idx}
            onClick={() => scrollToPanel(idx)}
            aria-label={`Go to panel ${idx}`}
            className={`w-2 h-2 rounded-full transition-all duration-300 ${
              activeDot === idx 
                ? 'bg-white scale-125' 
                : 'bg-white/30 hover:bg-white scale-100'
            }`}
          />
        ))}
      </div>
    </div>
  );
};

