</head>
<body class="bg-black overflow-hidden flex flex-col h-screen select-none">

    <!-- Cielo con WebGL (Fondo - Z 0) -->
    <div id="cielo-container" class="w-full flex-1 relative overflow-hidden" style="background: linear-gradient(180deg, #1E90FF 0%, #87CEFA 100%); z-index: 0;">
        <div id="three-canvas" class="absolute inset-0"></div>
    </div>

    <!-- Piso Fijo (Capa Base - Z 5) -->
    <div id="viewer" class="no-scrollbar relative" style="z-index: 5;">
        <div id="pane-0" class="pane relative">
            <img src="https://i.imgur.com/P2lPVcP.jpeg" class="img-left" alt="Sala Izquierda">
            <div class="absolute bottom-20 left-10 text-white/50 text-sm font-mono">VISTA OESTE</div>
        </div>
        <div id="pane-1" class="pane relative">
            <img src="https://i.imgur.com/P2lPVcP.jpeg" class="img-center" alt="Sala Centro">
            <div class="absolute bottom-20 left-1/2 -translate-x-1/2 text-white/50 text-sm font-mono">VISTA NORTE</div>
        </div>
        <div id="pane-2" class="pane relative">
            <img src="https://i.imgur.com/P2lPVcP.jpeg" class="img-right" alt="Sala Derecha">
            <div class="absolute bottom-20 right-10 text-white/50 text-sm font-mono">VISTA ESTE</div>
        </div>
    </div>

    <!-- Horizonte (Capa Intermedia - Z 10) -->
    <div id="horizon-wrapper">
        <div id="horizon-layer">
            <img src="https://i.imgur.com/qJjdsKJ.png" alt="Transición Horizonte">
        </div>
    </div>

    <!-- Indicadores UI (Capa Superior - Z 50) -->
    <div class="fixed bottom-6 left-1/2 -translate-x-1/2 flex gap-4 z-50 bg-black/40 backdrop-blur-md px-4 py-2 rounded-full border border-white/10 shadow-2xl transform transition-transform hover:scale-105">
        <div id="dot-0" class="w-2 h-2 rounded-full bg-white/30 cursor-pointer hover:bg-white transition-all duration-300"></div>
        <div id="dot-1" class="w-2 h-2 rounded-full bg-white cursor-pointer hover:bg-white transition-all duration-300 transform scale-125"></div>
        <div id="dot-2" class="w-2 h-2 rounded-full bg-white/30 cursor-pointer hover:bg-white transition-all duration-300"></div>
    </div>

    <script>
        // --- CONFIGURACIÓN THREE.JS OPTIMIZADA ---
        const CLOUD_URLS = [
            'https://i.imgur.com/JTrVDQ3.png', 'https://i.imgur.com/58lHfHw.png',
            'https://i.imgur.com/X8FIpPe.png', 'https://i.imgur.com/hcdTnXq.png',
            'https://i.imgur.com/C08w8E1.png', 'https://i.imgur.com/Nypf6gX.png',
            'https://i.imgur.com/jd76dmd.png'
        ];

        let scene, camera, renderer;
        let clouds = [];
        let animationId;

        // Estado del scroll
        let currentScrollX = 0;
        let targetScrollX = 0;
        let isScrolling = false;

        function initThree() {
            const container = document.getElementById('cielo-container');
            if (!container) return;

            const w = container.clientWidth;
            const h = container.clientHeight;
            const aspect = w / h;

            // 1. Escena Única
            scene = new THREE.Scene();

            // 2. Cámara Ortográfica para mantener consistencia 2D
            const frustumSize = 1000;
            camera = new THREE.OrthographicCamera(
                frustumSize * aspect / -2, 
                frustumSize * aspect / 2, 
                frustumSize / 2, 
                frustumSize / -2, 
                1, 
                2000
            );
            camera.position.z = 1000;

            // 3. Renderer Único
            renderer = new THREE.WebGLRenderer({ alpha: true, antialias: false, powerPreference: "high-performance" });
            renderer.setSize(w, h);
            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
            document.getElementById('three-canvas').appendChild(renderer.domElement);

            // 4. Carga de Texturas y Creación de Nubes
            const loader = new THREE.TextureLoader();
            const cloudGeo = new THREE.PlaneGeometry(300, 200);

            // Crear 15 nubes distribuidas
            for (let i = 0; i < 15; i++) {
                const url = CLOUD_URLS[i % CLOUD_URLS.length];
                loader.load(url, (texture) => {
                    const material = new THREE.MeshBasicMaterial({ 
                        map: texture, 
                        transparent: true,
                        depthWrite: false, 
                    });

                    const sprite = new THREE.Mesh(cloudGeo, material);

                    const isBack = i % 3 === 0; 
                    const isMid = i % 3 === 1;

                    setupCloud(sprite, isBack, isMid, w, h);
                    scene.add(sprite);
                    clouds.push(sprite);
                });
            }

            animate();
        }

        function setupCloud(sprite, isBack, isMid, w, h) {
            const rangeX = w * 1.5;
            const rangeY = h * 0.8;

