import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

const CLOUD_URLS = [
    'https://i.imgur.com/JTrVDQ3.png', 'https://i.imgur.com/58lHfHw.png',
    'https://i.imgur.com/X8FIpPe.png', 'https://i.imgur.com/hcdTnXq.png',
    'https://i.imgur.com/C08w8E1.png', 'https://i.imgur.com/Nypf6gX.png',
    'https://i.imgur.com/jd76dmd.png'
];

interface ThreeSkyProps {
    scrollRef: React.MutableRefObject<number>;
}

export const ThreeSky: React.FC<ThreeSkyProps> = ({ scrollRef }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        const aspect = w / h;

        // 1. Escena
        const scene = new THREE.Scene();

        // 2. Cámara Ortográfica
        const frustumSize = 1000;
        const camera = new THREE.OrthographicCamera(
            frustumSize * aspect / -2,
            frustumSize * aspect / 2,
            frustumSize / 2,
            frustumSize / -2,
            1,
            2000
        );
        camera.position.z = 1000;

        // 3. Renderer
        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: false, powerPreference: "high-performance" });
        renderer.setSize(w, h);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        // 4. Nubes
        const clouds: THREE.Mesh[] = [];
        const loader = new THREE.TextureLoader();
        const cloudGeo = new THREE.PlaneGeometry(300, 200);

        const setupCloud = (sprite: THREE.Mesh, isBack: boolean, isMid: boolean, width: number, height: number) => {
            const rangeX = width * 1.5;
            const rangeY = height * 0.8;

            sprite.position.x = (Math.random() * rangeX * 2) - rangeX;
            sprite.position.y = (Math.random() * rangeY) - (rangeY / 2);

            if (isBack) {
                sprite.position.z = -100;
                sprite.scale.set(1.5, 1.5, 1);
                // @ts-ignore
                sprite.material.opacity = 0.4;
                sprite.userData = { speed: 0.2, parallax: 0.1 };
            } else if (isMid) {
                sprite.position.z = 0;
                sprite.scale.set(1.2, 1.2, 1);
                // @ts-ignore
                sprite.material.opacity = 0.8;
                sprite.userData = { speed: 0.5, parallax: 0.3 };
            } else {
                sprite.position.z = 100;
                sprite.scale.set(1.8, 1.8, 1);
                // @ts-ignore
                sprite.material.opacity = 1.0;
                sprite.userData = { speed: 0.8, parallax: 0.6 };
            }
        };

        for (let i = 0; i < 15; i++) {
            const url = CLOUD_URLS[i % CLOUD_URLS.length];
            loader.load(url, (texture) => {
                const material = new THREE.MeshBasicMaterial({
                    map: texture,
                    transparent: true,
                    depthWrite: false,
                });

                const sprite = new THREE.Mesh(cloudGeo, material);
                const isBack = i % 3 === 0;
                const isMid = i % 3 === 1;

                setupCloud(sprite, isBack, isMid, w, h);
                scene.add(sprite);
                clouds.push(sprite);
            });
        }

        // 5. Animación
        let animationId: number;
        const animate = () => {
            animationId = requestAnimationFrame(animate);

            const viewerWidth = window.innerWidth;
            // Usamos el ref para obtener el scroll actual sin re-renderizar React
            const currentScrollX = scrollRef.current;
            const relativeScroll = currentScrollX - viewerWidth;

            clouds.forEach(cloud => {
                cloud.position.x -= cloud.userData.speed;

                if (cloud.position.x < -viewerWidth * 1.5) {
                    cloud.position.x = viewerWidth * 1.5;
                    // Reset base when looping
                    cloud.userData.baseX = viewerWidth * 1.5; 
                }

                if (cloud.userData.baseX === undefined) cloud.userData.baseX = cloud.position.x;

                cloud.userData.baseX -= cloud.userData.speed;
                if (cloud.userData.baseX < -viewerWidth * 1.5) cloud.userData.baseX = viewerWidth * 1.5;

                cloud.position.x = cloud.userData.baseX - (relativeScroll * cloud.userData.parallax);
            });

            renderer.render(scene, camera);
        };

        animate();

        // 6. Resize
        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            const newAspect = newW / newH;

            camera.left = -frustumSize * newAspect / 2;
            camera.right = frustumSize * newAspect / 2;
            camera.top = frustumSize / 2;
            camera.bottom = -frustumSize / 2;
            camera.updateProjectionMatrix();

            renderer.setSize(newW, newH);
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            if (containerRef.current) {
                containerRef.current.removeChild(renderer.domElement);
            }
            renderer.dispose();
        };
    }, []); // Empty dependency array, runs once on mount

    return (
        <div 
            id="cielo-container" 
            ref={containerRef}
            className="w-full flex-1 relative overflow-hidden" 
            style={{ background: 'linear-gradient(180deg, #1E90FF 0%, #87CEFA 100%)', zIndex: 0 }}
        />
    );
};

