                </div>
                <div className="bg-black/80 backdrop-blur-md text-white px-6 py-4 border-l-4 border-yellow-400 max-w-md">
                    <p className="font-mono text-sm md:text-base leading-relaxed text-gray-300">
                        {subtitle}
                    </p>
                </div>
            </div>
        );
    };

    return (
        <div className="bg-gray-900 overflow-hidden flex flex-col h-screen select-none relative font-sans">

