                <div className="pane relative min-w-[100vw] w-[100vw] h-full flex-shrink-0 bg-black overflow-hidden snap-start border-r-4 border-black/50">
                    <img src="https://i.imgur.com/P2lPVcP.jpeg" className="pane-img img-left opacity-60 grayscale" alt="Skills Background" />
                    <SectionTitle 
                        title="Habilidades / Stats" 
                        subtitle="LVL 99 DEVELOPER. Especializado en React, WebGL y Arquitectura Frontend. Daño crítico en optimización de renderizado." 
                        align="left"
                    />
                </div>

                {/* Pane 1: HOME (Centro) */}
                <div className="pane relative min-w-[100vw] w-[100vw] h-full flex-shrink-0 bg-black overflow-hidden snap-start">
                    {/* Imagen principal con menos filtro para destacar */}
                    <img src="https://i.imgur.com/P2lPVcP.jpeg" className="pane-img img-center opacity-80" alt="Main Character" />
                    <SectionTitle 
                        title="Unibelands 3" 
                        subtitle="Bienvenido al Desierto Digital. Explora mi portafolio interactivo. Desliza o usa el HUD inferior para navegar." 
                        align="center"
                    />
                </div>

