            id="sand-storm-wrapper" 
            className="absolute left-0 w-full z-20 pointer-events-none overflow-hidden bottom-[50vh] h-[40vh] mask-fog-gradient"
        >

            {/* Capa contenedora para PARALLAX (controlada por JS/Props) */}
            <div id="sand-parallax-layer" 
                 className="w-[300vw] h-full relative will-change-transform"
                 style={{ 
                     transform: `translateX(-${parallaxX}px)` 
                 }}>

                {/* Textura de grano ruidoso */}
                <div className="absolute inset-[-50%] w-[200%] h-[200%] opacity-15 mix-blend-overlay z-21 bg-noise-texture animate-grain"></div>

