                    <p className="font-mono text-xs md:text-sm leading-relaxed text-gray-300">
                        {subtitle}
                    </p>
                </div>
            </div>
        );
    };

    return (
        <div className="bg-gray-900 overflow-hidden flex flex-col h-screen select-none relative font-sans">

            <ThreeSky scrollRef={scrollRef} />

