                    <GameImage 
                        src="https://i.imgur.com/P2lPVcP.jpeg" 
                        alt="Skills Background" 
                        className="opacity-60 grayscale"
                        priority={false} 
                    />
                    <SectionTitle 
                        title="Habilidades" 
                        subtitle="LVL 99 DEVELOPER. Especializado en React, WebGL y Arquitectura Frontend. Optimización de renderizado al máximo." 
                        align="left"
                    />
                </div>

                {/* Pane 1: HOME (Centro - Prioridad Alta) */}
                <div className="pane relative min-w-[100vw] w-[100vw] h-full flex-shrink-0 bg-black overflow-hidden snap-start">
                    <GameImage 
                        src="https://i.imgur.com/P2lPVcP.jpeg" 
                        alt="Main Character" 
                        priority={true} 
                    />
                    <SectionTitle 
                        title="Unibelands 3" 
                        subtitle="Bienvenido al Desierto Digital. Explora mi portafolio interactivo. Desliza o usa el HUD inferior." 
                        align="center"
                    />
                </div>

                {/* Pane 2: PROJECTS */}
                <div className="pane relative min-w-[100vw] w-[100vw] h-full flex-shrink-0 bg-black overflow-hidden snap-start border-l-4 border-black/50">
                    <GameImage 
                        src="https://i.imgur.com/P2lPVcP.jpeg" 
                        alt="Projects Background" 
                        className="opacity-60 grayscale"
                        priority={false} 
                    />
                    <SectionTitle 
                        title="Misiones" 
                        subtitle="Historial de proyectos completados. Desde aplicaciones SaaS corporativas hasta experiencias inmersivas." 
                        align="right"
                    />
                </div>
            </div>

            <Horizon parallaxX={scrollX * 0.5} />
            <SandFog parallaxX={scrollX * 0.7} />

