interface SandFogProps {
    parallaxX: number;
}

export const SandFog: React.FC<SandFogProps> = ({ parallaxX }) => {
    return (
        <div 
            id="sand-storm-wrapper" 
            // Usamos [mask-image:...] para el desvanecimiento sin CSS externo
            className="absolute left-0 w-full z-20 pointer-events-none overflow-hidden bottom-[50vh] h-[40vh] [mask-image:linear-gradient(to_bottom,transparent,black_20%,black_80%,transparent)]"
        >

            <div id="sand-parallax-layer" 
                 className="w-[300vw] h-full relative will-change-transform"
                 style={{ 
                     transform: `translateX(-${parallaxX}px)` 
                 }}>

                {/* Textura de ruido SVG inyectada directamente en la clase utilitaria */}
                <div className="absolute inset-[-50%] w-[200%] h-[200%] opacity-15 mix-blend-overlay z-21 bg-[url('data:image/svg+xml,%3Csvg_viewBox=%270_0_200_200%27_xmlns=%27http://www.w3.org/2000/svg%27%3E%3Cfilter_id=%27noiseFilter%27%3E%3CfeTurbulence_type=%27fractalNoise%27_baseFrequency=%270.65%27_numOctaves=%273%27_stitchTiles=%27stitch%27/%3E%3C/filter%3E%3Crect_width=%27100%25%27_height=%27100%25%27_filter=%27url(%23noiseFilter)%27_opacity=%271%27/%3E%3C/svg%3E')] animate-grain"></div>

                <div className="flex w-[150%] h-full absolute animate-drift">
                    {[...Array(6)].map((_, i) => {
                        const isEven = i % 2 === 0;
                        const isThird = i % 3 === 0;

                        let classes = "flex-shrink-0 rounded-[50%] -ml-[12vw] blur-xl ";
                        let blobStyle: React.CSSProperties = {};

                        if (isEven) {
                            classes += "w-[75vw] h-[40vh] animate-blob-2 ";
                            blobStyle = {
                                background: 'radial-gradient(circle at center, rgba(245, 235, 220, 0.9), rgba(220, 200, 170, 0.3), transparent 65%)',
                                animationDelay: '-5s',
                                transform: 'translateY(15px)'
                            };
                        } else if (isThird) {
                            classes += "w-[55vw] h-[30vh] blur-2xl animate-blob-3 ";
                            blobStyle = {
                                background: 'radial-gradient(circle at center, rgba(255, 250, 240, 0.6), transparent 70%)',
                                animationDelay: '-2s'
                            };
                        } else {
                            classes += "w-[60vw] h-[35vh] animate-blob-1 ";
                            blobStyle = {
                                background: 'radial-gradient(circle at center, rgba(230, 218, 195, 0.85), rgba(210, 180, 140, 0.4), transparent 70%)'
                            };
                        }

                        return <div key={i} className={classes} style={blobStyle} />;
                    })}
                </div>
            </div>
        </div>
    );
};

