                        </div>
                    </div>
                </div>
            )}

            <img
                src={src}
                alt={alt}
                // Estrategia de carga moderna para velocidad espectacular
                loading={priority ? "eager" : "lazy"}
                // @ts-ignore: React types might not yet include fetchPriority
                fetchPriority={priority ? "high" : "low"}
                decoding="async"
