        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: false, powerPreference: "high-performance" });
        renderer.setSize(w, h);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        // 4. Nubes
        const clouds: THREE.Mesh[] = [];
        const loader = new THREE.TextureLoader();
        const cloudGeo = new THREE.PlaneGeometry(300, 200);

        const setupCloud = (sprite: THREE.Mesh, isBack: boolean, isMid: boolean, width: number, height: number) => {
            // Aumentamos el rango drásticamente para cubrir las 3 vistas completas
            const rangeX = width * 2.0; 
            const rangeY = height * 1.0; // Usar todo el alto

            sprite.position.x = (Math.random() * rangeX * 2) - rangeX;
            sprite.position.y = (Math.random() * rangeY) - (rangeY / 2);

            if (isBack) {
                sprite.position.z = -100;
                sprite.scale.set(2.0, 2.0, 1); // Más grandes para rellenar fondo
                // @ts-ignore
                sprite.material.opacity = 0.5;
                sprite.userData = { speed: 0.2, parallax: 0.1 };
            } else if (isMid) {
                sprite.position.z = 0;
                sprite.scale.set(1.5, 1.5, 1);
                // @ts-ignore
                sprite.material.opacity = 0.8;
                sprite.userData = { speed: 0.5, parallax: 0.3 };
            } else {
                sprite.position.z = 100;
                sprite.scale.set(2.2, 2.2, 1); // Primer plano impactante
                // @ts-ignore
                sprite.material.opacity = 1.0;
                sprite.userData = { speed: 0.8, parallax: 0.6 };
            }

            // Inicializar baseX
            sprite.userData.baseX = sprite.position.x;
