                const sprite = new THREE.Mesh(cloudGeo, material);
                const isBack = i % 3 === 0;
                const isMid = i % 3 === 1;

                setupCloud(sprite, isBack, isMid, w, h);
                scene.add(sprite);
                clouds.push(sprite);
            });
        }

        // 5. Animación
        let animationId: number;
        const animate = () => {
            animationId = requestAnimationFrame(animate);

            const viewerWidth = window.innerWidth;
            const currentScrollX = scrollRef.current;
            const relativeScroll = currentScrollX - viewerWidth;

            // Límite de respawn ajustado al nuevo rango amplio
            const limitX = viewerWidth * 2.0;

            clouds.forEach(cloud => {
                // Movimiento base del viento
                cloud.userData.baseX -= cloud.userData.speed;

                // Loop infinito basado en posición lógica del mundo (baseX)
                if (cloud.userData.baseX < -limitX) {
                    cloud.userData.baseX = limitX;
                }

                // Cálculo de Parallax
                cloud.position.x = cloud.userData.baseX - (relativeScroll * cloud.userData.parallax);
            });

            renderer.render(scene, camera);
        };

        animate();

        // 6. Resize
        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            const newAspect = newW / newH;

            camera.left = -frustumSize * newAspect / 2;
            camera.right = frustumSize * newAspect / 2;
            camera.top = frustumSize / 2;
            camera.bottom = -frustumSize / 2;
            camera.updateProjectionMatrix();

            renderer.setSize(newW, newH);
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            if (containerRef.current) {
                containerRef.current.removeChild(renderer.domElement);
            }
            renderer.dispose();
        };
    }, []);

    return (
        <div 
            id="cielo-container" 
            ref={containerRef}
            className="w-full flex-1 relative overflow-hidden" 
            style={{ background: 'linear-gradient(180deg, #1E90FF 0%, #87CEFA 100%)', zIndex: 0 }}
        />
    );
};

