        // El ancho de la cámara es (frustumSize * aspect)
        // Multiplicamos por 4 para tener espacio de sobra a derecha e izquierda
        const getSceneWidth = () => 1000 * (containerRef.current?.clientWidth || 1000) / (containerRef.current?.clientHeight || 1000);

        const setupCloud = (sprite: THREE.Mesh, layerIndex: number) => {
            const sceneW = getSceneWidth();
            const rangeX = sceneW * 4.0; // Espacio total de distribución (2 pantallas a cada lado)
            const rangeY = 1000; // Altura del frustum

            // Posición inicial distribuida aleatoriamente en todo el rango
            sprite.position.x = (Math.random() * rangeX) - (rangeX / 2);

