                sprite.position.y = (Math.random() * rangeY * 0.5) + (rangeY * 0.1); 
                const scale = 2.5 + Math.random() * 1.5; 
                sprite.scale.set(scale * flip, scale, 1);
                // @ts-ignore
                sprite.material.opacity = 0.4 + Math.random() * 0.2;
