            // scrollRef está en pixeles. Necesitamos saber cuánto es eso en el mundo 3D.
            // Si el ancho de pantalla (pixels) equivale a sceneVisibleWidth (unidades), entonces:
            const pixelToUnitRatio = sceneVisibleWidth / currentW;

            // Calculamos el offset de scroll en unidades del mundo 3D
            const scrollOffsetUnits = scrollRef.current * pixelToUnitRatio;
            // Centramos el scroll (para que parallax funcione desde el centro)
            const relativeScrollUnits = scrollOffsetUnits - (sceneVisibleWidth / 2); 
