            // Debe ser mayor que: Mitad del ancho visible + Margen Parallax + Ancho Nube
            // Usamos un límite muy generoso para asegurar que salgan totalmente de pantalla
            const respawnLimit = sceneVisibleWidth * 2.5; 

            clouds.forEach(cloud => {
                // 1. Movimiento del viento (Siempre hacia la izquierda, negativo)
                cloud.userData.baseX -= cloud.userData.speed;

                // 2. Parallax
                // Aplicamos el parallax sobre la posición base.
                // Como las nubes están en baseX, restamos el scroll afectado por factor parallax
                const parallaxEffect = (scrollRef.current - window.innerWidth) * pixelToUnitRatio * cloud.userData.parallax;

                // Posición visual final
                const finalX = cloud.userData.baseX - parallaxEffect;

                // 3. Lógica de Loop (Reinicio)
                // Verificamos si la nube visualmente ya pasó el límite izquierdo
                // El límite es negativo (izquierda).
                if (finalX < -respawnLimit) {
                    // Si se salió por la izquierda, la mandamos a la DERECHA LEJANA
                    // Calculamos cuánto hay que sumar a baseX para que aparezca al otro lado
                    // Distancia total de viaje = respawnLimit * 2
                    // Ajustamos baseX para que, con el parallax actual, aparezca en +respawnLimit
                    cloud.userData.baseX += (respawnLimit * 2);
                }
            });

            // Actualizar posiciones visuales
            clouds.forEach(cloud => {
                 const parallaxEffect = (scrollRef.current - window.innerWidth) * pixelToUnitRatio * cloud.userData.parallax;
                 cloud.position.x = cloud.userData.baseX - parallaxEffect;
            });

            renderer.render(scene, camera);
        };

        animate();

        // 6. Resize
        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
