                    sprite.position.y = (Math.random() * rangeY * 0.8) - (rangeY * 0.1); 
                    const scale = 2.5 + Math.random() * 1.5; 
                    sprite.scale.set(scale * flip, scale, 1);
                    // @ts-ignore
                    sprite.material.opacity = 0.4 + Math.random() * 0.2;
                    sprite.userData = { speed: 0.3, parallax: 0.05, baseX: sprite.position.x };

                } else if (layerIndex === 1) {
                    // Medio
                    sprite.position.z = -50;
                    sprite.position.y = (Math.random() * rangeY * 0.9) - (rangeY * 0.2);
                    const scale = 1.8 + Math.random() * 0.8;
                    sprite.scale.set(scale * flip, scale, 1);
                    // @ts-ignore
                    sprite.material.opacity = 0.8 + Math.random() * 0.2;
                    sprite.userData = { speed: 0.6, parallax: 0.15, baseX: sprite.position.x };

                } else {
                    // Frente
                    sprite.position.z = 100;
                    sprite.position.y = (Math.random() * rangeY) - (rangeY * 0.5);
                    const scale = 1.5 + Math.random() * 1.0;
                    sprite.scale.set(scale * flip, scale, 1);
                    // @ts-ignore
                    sprite.material.opacity = 0.95 + Math.random() * 0.05;
                    sprite.userData = { speed: 1.0, parallax: 0.3, baseX: sprite.position.x };
                }
            }
        };

        const CLOUD_COUNT = 24;

        for (let i = 0; i < CLOUD_COUNT; i++) {
            const url = CLOUD_URLS[i % CLOUD_URLS.length];
            loader.load(url, (texture) => {
                const material = new THREE.MeshBasicMaterial({
                    map: texture,
                    transparent: true,
                    depthWrite: false,
                });

                const sprite = new THREE.Mesh(cloudGeo, material);
                setupCloud(sprite, i); // Pasamos el índice para la lógica de Mega Nube
                scene.add(sprite);
                clouds.push(sprite);
            });
        }

        // 5. Animación
        let animationId: number;
        const animate = () => {
            animationId = requestAnimationFrame(animate);

            if (!containerRef.current) return;

            const currentW = containerRef.current.clientWidth;
            const currentAspect = currentW / containerRef.current.clientHeight;
            const sceneVisibleWidth = 1000 * currentAspect;

            const pixelToUnitRatio = sceneVisibleWidth / currentW;

            // Aumentamos el límite de respawn considerablemente porque las Mega Nubes son enormes
            // y no queremos que desaparezcan (pop) mientras su "cola" sigue en pantalla.
            const respawnLimit = sceneVisibleWidth * 3.5; 

            clouds.forEach(cloud => {
                cloud.userData.baseX -= cloud.userData.speed;

                const parallaxEffect = (scrollRef.current - window.innerWidth) * pixelToUnitRatio * cloud.userData.parallax;
                const finalX = cloud.userData.baseX - parallaxEffect;

                // Lógica de Loop
                if (finalX < -respawnLimit) {
                    // Reiniciar al otro lado (Derecha lejana)
                    // Usamos un factor aleatorio pequeño en el respawn para romper patrones repetitivos con el tiempo
                    const randomBuffer = Math.random() * 500;
                    cloud.userData.baseX += (respawnLimit * 2) + randomBuffer;
                }
            });

            // Update visual
            clouds.forEach(cloud => {
                 const parallaxEffect = (scrollRef.current - window.innerWidth) * pixelToUnitRatio * cloud.userData.parallax;
                 cloud.position.x = cloud.userData.baseX - parallaxEffect;
            });

            renderer.render(scene, camera);
        };

        animate();

        // 6. Resize
        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            const newAspect = newW / newH;

            camera.left = -frustumSize * newAspect / 2;
            camera.right = frustumSize * newAspect / 2;
            camera.top = frustumSize / 2;
            camera.bottom = -frustumSize / 2;
            camera.updateProjectionMatrix();

            renderer.setSize(newW, newH);
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            if (containerRef.current) {
                containerRef.current.removeChild(renderer.domElement);
            }
            renderer.dispose();
        };
    }, []);

    return (
        <div 
            id="cielo-container" 
            ref={containerRef}
            className="w-full flex-1 relative overflow-hidden" 
            style={{ background: 'linear-gradient(180deg, #1E90FF 0%, #87CEFA 100%)', zIndex: 0 }}
        />
    );
};

