                cloud.userData.baseX -= cloud.userData.speed;

                const parallaxEffect = (scrollRef.current - window.innerWidth) * pixelToUnitRatio * cloud.userData.parallax;
                const finalX = cloud.userData.baseX - parallaxEffect;

                // Lógica de Loop
                if (finalX < -respawnLimit) {
                    const randomBuffer = Math.random() * 500;
                    cloud.userData.baseX += (respawnLimit * 2) + randomBuffer;
                }
            });

            // Update visual
            clouds.forEach(cloud => {
                 const parallaxEffect = (scrollRef.current - window.innerWidth) * pixelToUnitRatio * cloud.userData.parallax;
                 cloud.position.x = cloud.userData.baseX - parallaxEffect;
            });

            renderer.render(scene, camera);
        };

        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            const newAspect = newW / newH;

            camera.left = -frustumSize * newAspect / 2;
            camera.right = frustumSize * newAspect / 2;
            camera.top = frustumSize / 2;
            camera.bottom = -frustumSize / 2;
            camera.updateProjectionMatrix();

            renderer.setSize(newW, newH);
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            if (containerRef.current) {
                containerRef.current.removeChild(renderer.domElement);
            }
            renderer.dispose();
        };
    }, []);

    return (
        <div 
            id="cielo-container" 
            ref={containerRef}
            className="w-full flex-1 relative overflow-hidden" 
            style={{ background: 'linear-gradient(180deg, #1E90FF 0%, #87CEFA 100%)', zIndex: 0 }}
        />
    );
};

import React, { useRef, useState, useEffect } from 'react';
import { ThreeSky } from './components/clouds/ThreeSky';
import { SandFog } from './components/special-effects/SandFog';
import { Horizon } from './components/special-effects/Horizon';
import { Navigation } from './components/ui/Navigation';
import { GameImage } from './components/ui/GameImage';

const App: React.FC = () => {
    const viewerRef = useRef<HTMLDivElement>(null);
    const scrollRef = useRef<number>(0); 
    const [scrollX, setScrollX] = useState(0); 
    const [activeIndex, setActiveIndex] = useState(1); 
    const [windowWidth, setWindowWidth] = useState(0);

    useEffect(() => {
        // Inicializar width
        setWindowWidth(window.innerWidth);

        if (viewerRef.current) {
            const startX = window.innerWidth;
            viewerRef.current.scrollTo({ left: startX, behavior: 'auto' });
            scrollRef.current = startX;
            setScrollX(startX);
        }

        const handleScroll = () => {
            if (viewerRef.current) {
                const currentX = viewerRef.current.scrollLeft;
                scrollRef.current = currentX; 

                requestAnimationFrame(() => {
                    setScrollX(currentX);
                    setActiveIndex(Math.round(currentX / window.innerWidth));
                });
            }
        };

        const handleResize = () => {
            setWindowWidth(window.innerWidth);
        };

        const currentViewer = viewerRef.current;
        if (currentViewer) {
            currentViewer.addEventListener('scroll', handleScroll, { passive: true });
        }
        window.addEventListener('resize', handleResize);

        return () => {
            if (currentViewer) {
                currentViewer.removeEventListener('scroll', handleScroll);
            }
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    const handleDotClick = (index: number) => {
        if (viewerRef.current) {
            const target = index * window.innerWidth;
            viewerRef.current.scrollTo({ left: target, behavior: 'smooth' });
        }
    };

    // CÁLCULO DE PARALAJE DEL HORIZONTE PARA ALINEACIÓN NORTE
    // Queremos que cuando scrollX == windowWidth (Vista Norte/Centro),
    // el desplazamiento del horizonte sea tal que muestre exactamente su centro.
    // Fórmula: offset = (scrollX * 0.5) + (windowWidth * 0.5)
    // - En Scroll W (Norte): W*0.5 + W*0.5 = W. Horizon se mueve -W. Se ve la parte central (de W a 2W).
    const horizonParallax = (scrollX * 0.5) + (windowWidth * 0.5);

    return (
        <div className="bg-gray-900 overflow-hidden flex flex-col h-screen select-none relative font-sans text-white">

            <ThreeSky scrollRef={scrollRef} />

            {/* Visor Principal */}
            <div 
                ref={viewerRef}
                id="viewer" 
                className="relative flex flex-row w-full overflow-x-auto scroll-smooth snap-x snap-mandatory [&::-webkit-scrollbar]:hidden [-ms-overflow-style:'none'] [scrollbar-width:'none']"
                style={{ height: '70vh', minHeight: '400px', zIndex: 5 }}
            >
                {/* Pane 0: Izquierda */}
                <div className="pane relative min-w-[100vw] w-[100vw] h-full flex-shrink-0 bg-black overflow-hidden snap-start">
                    <GameImage 
                        src="https://i.imgur.com/P2lPVcP.jpeg" 
                        alt="Sala Izquierda" 
                        className="opacity-100"
                        priority={false} 
                    />
                    <div className="absolute bottom-20 left-10 text-white/50 text-sm font-mono">VISTA OESTE</div>
                </div>

                {/* Pane 1: Centro (Carga Prioritaria) */}
                <div className="pane relative min-w-[100vw] w-[100vw] h-full flex-shrink-0 bg-black overflow-hidden snap-start">
                    <GameImage 
                        src="https://i.imgur.com/P2lPVcP.jpeg" 
                        alt="Sala Centro" 
                        priority={true} 
                    />
                    <div className="absolute bottom-20 left-1/2 -translate-x-1/2 text-white/50 text-sm font-mono">VISTA NORTE</div>
                </div>

                {/* Pane 2: Derecha */}
                <div className="pane relative min-w-[100vw] w-[100vw] h-full flex-shrink-0 bg-black overflow-hidden snap-start">
                    <GameImage 
                        src="https://i.imgur.com/P2lPVcP.jpeg" 
                        alt="Sala Derecha" 
                        className="opacity-100"
                        priority={false} 
                    />
                    <div className="absolute bottom-20 right-10 text-white/50 text-sm font-mono">VISTA ESTE</div>
                </div>
            </div>

            <Horizon parallaxX={horizonParallax} />
            <SandFog parallaxX={scrollX * 0.7} />

            <Navigation totalPanes={3} activeIndex={activeIndex} onDotClick={handleDotClick} />

        </div>
    );
};

export default App;

import React from 'react';

interface HorizonProps {
    parallaxX: number;
}

export const Horizon: React.FC<HorizonProps> = ({ parallaxX }) => {
    return (
        <div id="horizon-wrapper" className="absolute left-0 w-full z-10 pointer-events-none overflow-hidden"
             style={{
                 bottom: 'calc(70vh - 25px)',
                 height: '18vh',
                 minHeight: '100px'
             }}>
            <div id="horizon-layer" className="flex w-[300vw] h-full will-change-transform"
                 style={{ transform: `translateX(-${parallaxX}px)` }}>
                <img src="https://i.imgur.com/qJjdsKJ.png" alt="Transición Horizonte" 
                     className="w-full h-full object-cover object-bottom opacity-90" />
            </div>
        </div>
    );
};
